  $json${"schema_version":"1.0","module_id":"GA-A1-M02","kind":"training_module","format_profile":"ga_training_module_v1","level":"A1","sequence":2,"title":"Familie & Personen","theme":"Parler de sa famille et décrire des personnes simplement","subtitle":"Module d’entraînement A1 — German Academy (pas un examen blanc)","estimated_minutes":30,"prerequisites":["Recommandé (non bloquant) : GA-A1-M01 — ordre 1, ~30 min. Sortie M01 attendue : saluer, se présenter (heißen / kommen / wohnen / sein). Vocabulaire réutilisé : Hallo, Guten Tag, heißen, sein, Studentin, Lehrer. Nouvelles notions M02 : Familie, haben, mein/meine, der/die/das, Berufe, wie alt, wer. Le runner n’impose pas encore ce prérequis."],"learning_objectives":["Présenter les membres d’une famille","Indiquer une relation familiale simple","Parler de l’âge et de la profession","Décrire une personne avec quelques adjectifs","Utiliser haben au présent","Utiliser mein/meine et dein/deine","Reconnaître der, die, das","Poser des questions avec wer, wie alt, was"],"vocabulary_targets":["Mutter","Vater","Schwester","Bruder","Kind","Familie","Freund","Freundin","Lehrerin","Arzt","Ärztin","Schüler","Student","Studentin","Jahre alt","nett","freundlich"],"grammar_targets":["haben (ich habe, Sie haben)","Possessivartikel mein/meine, dein/deine","Artikel der/die/das","W-Fragen: wer, wie alt, was","Adjektive prädikativ (ist nett)","Beruf + sein"],"skills":["wortschatz","grammatik","lesen","hoeren","schreiben","sprechen","revision"],"publication_status":"draft","provenance":{"content_origin":"original","publisher_content_embedded":false,"commercial_media_used":false,"author":"German Academy","created_at":"2026-09-28","updated_at":"2026-09-28","version":"1.0.2"},"media":{"audio_tracks":[{"id":"GA-A1-M02-AUD-01","url":"/exam-media/ga-a1-m02/hoeren-familie.mp3","duration_seconds":23,"script_staff_only":"Ansage: Hören Sie den Dialog. Frau: Hallo! Das ist meine Familie. Das ist mein Bruder Omar. Er ist 16 Jahre alt und Schüler. Mann: Und wer ist das? Frau: Das ist meine Mutter Laila. Sie ist Ärztin und sehr freundlich."}]},"correction":{"show_keys_before_submit":false,"allow_retry":true,"practice_scoring":true,"goethe_scoring":false,"pass_fail_certificate":false,"timed_exam":false},"activities":[{"id":"GA-A1-M02-W01","order":1,"skill":"wortschatz","activity_type":"single_choice","learning_objective":"Identifier le mot « Mutter »","theme":"Familie","focus":"Mutter / Vater / Bruder","difficulty":"guided","instruction":"Wählen Sie die passende Antwort.","prompt":"Meine Schwester und ich haben dieselbe ___.","points":1,"choices":[{"id":"A","text":"Schwester"},{"id":"B","text":"Mutter"},{"id":"C","text":"Tochter"}],"correct_answer":"B","explanation":"Geschwister haben dieselbe Mutter.","positive_feedback":"Richtig — Mutter.","common_error":"Schwester und Tochter sind andere Familienmitglieder."},{"id":"GA-A1-M02-W02","order":2,"skill":"wortschatz","activity_type":"single_choice","learning_objective":"Associer une profession simple","theme":"Beruf","focus":"Ärztin / Lehrerin / Studentin","difficulty":"guided","instruction":"Wählen Sie die passende Antwort.","prompt":"Sie arbeitet im Krankenhaus. Sie ist …","points":1,"choices":[{"id":"A","text":"Lehrerin"},{"id":"B","text":"Ärztin"},{"id":"C","text":"Studentin"}],"correct_answer":"B","explanation":"Im Krankenhaus arbeitet eine Ärztin (oder ein Arzt). Hier ist die Form feminin: Ärztin.","positive_feedback":"Genau — Ärztin.","common_error":"Lehrerin arbeitet in der Schule; Studentin studiert."},{"id":"GA-A1-M02-G01","order":3,"skill":"grammatik","activity_type":"single_choice","learning_objective":"Conjuguer haben à la 1re personne","theme":"haben","focus":"ich habe","difficulty":"guided","instruction":"Wählen Sie die richtige Form.","prompt":"Ich ___ zwei Geschwister.","points":1,"choices":[{"id":"A","text":"habe"},{"id":"B","text":"hast"},{"id":"C","text":"hat"}],"correct_answer":"A","explanation":"Mit ich: ich habe.","positive_feedback":"Richtig — ich habe.","common_error":"hast ist für du, hat für er/sie/es."},{"id":"GA-A1-M02-G02","order":4,"skill":"grammatik","activity_type":"form_fill","learning_objective":"Utiliser mein / meine selon le genre","theme":"Possessivartikel","focus":"mein Bruder / meine Schwester","difficulty":"semi_guided","instruction":"Ergänzen Sie mein oder meine.","prompt":"Das ist ___ Bruder. Das ist ___ Schwester.","points":2,"fields":[{"id":"1","label":"Lücke 1 (Bruder)"},{"id":"2","label":"Lücke 2 (Schwester)"}],"correct_form":{"1":"mein","2":"meine"},"explanation":"Bruder ist maskulin → mein. Schwester ist feminin → meine.","positive_feedback":"Sehr gut — mein / meine.","common_error":"Viele Personen schreiben meine Bruder — falsch."},{"id":"GA-A1-M02-G03","order":5,"skill":"grammatik","activity_type":"single_choice","learning_objective":"Choisir l’article correct","theme":"Artikel","focus":"der / die / das","difficulty":"guided","instruction":"Wählen Sie den richtigen Artikel.","prompt":"___ Vater arbeitet in Paris.","points":1,"choices":[{"id":"A","text":"Die"},{"id":"B","text":"Das"},{"id":"C","text":"Der"}],"correct_answer":"C","explanation":"Vater ist maskulin: der Vater.","positive_feedback":"Richtig — der Vater.","common_error":"die Vater ist falsch."},{"id":"GA-A1-M02-G04","order":6,"skill":"grammatik","activity_type":"single_choice","learning_objective":"Choisir la question pour l’âge","theme":"W-Fragen","focus":"wie alt","difficulty":"guided","instruction":"Wählen Sie die passende Frage.","prompt":"Sie möchten das Alter wissen. Was fragen Sie?","points":1,"choices":[{"id":"A","text":"Wer sind Sie?"},{"id":"B","text":"Wie alt sind Sie?"},{"id":"C","text":"Was machen Sie?"}],"correct_answer":"B","explanation":"Für das Alter: Wie alt sind Sie?","positive_feedback":"Genau — Wie alt …?","common_error":"Wer fragt nach der Person, nicht nach dem Alter."},{"id":"GA-A1-M02-G05","order":7,"skill":"grammatik","activity_type":"single_choice","learning_objective":"Décrire avec un adjectif simple","theme":"Beschreibung","focus":"ist nett","difficulty":"guided","instruction":"Wählen Sie die passende Antwort.","prompt":"Mein Freund ist sehr …","points":1,"choices":[{"id":"A","text":"nett"},{"id":"B","text":"Lehrerin"},{"id":"C","text":"Familie"}],"correct_answer":"A","explanation":"Nach sein steht oft ein Adjektiv: er ist nett.","positive_feedback":"Richtig — nett.","common_error":"Lehrerin und Familie sind keine Adjektive."},{"id":"GA-A1-M02-L01","order":8,"skill":"lesen","activity_type":"true_false","learning_objective":"Comprendre un court texte sur une famille","theme":"Lesen Familie","focus":"Compréhension globale","difficulty":"semi_guided","instruction":"Lesen Sie den Text. Ist der Satz richtig oder falsch?","prompt":"Sara hat einen Bruder und eine Schwester.","points":1,"passage":"Hallo, ich heiße Sara. Ich habe einen Bruder. Er heißt Yassin. Ich habe keine Schwester. Meine Mutter ist Lehrerin.","choices":[{"id":"true","text":"Richtig"},{"id":"false","text":"Falsch"}],"correct_answer":false,"explanation":"Sara hat einen Bruder, aber keine Schwester.","positive_feedback":"Gut gelesen.","common_error":"Der Text sagt ausdrücklich: keine Schwester."},{"id":"GA-A1-M02-H01","order":9,"skill":"hoeren","activity_type":"listening","learning_objective":"Comprendre le nom du frère dans le dialogue","theme":"Hören Familie","focus":"Name des Bruders","difficulty":"semi_guided","instruction":"Hören Sie den Dialog. Wählen Sie die richtige Antwort.","prompt":"Wie heißt der Bruder?","points":1,"choices":[{"id":"A","text":"Omar"},{"id":"B","text":"Karim"},{"id":"C","text":"Yassin"}],"correct_answer":"A","explanation":"Die Frau sagt: mein Bruder Omar.","positive_feedback":"Richtig gehört — Omar.","common_error":"Laila ist die Mutter, nicht der Bruder.","media":{"audio_url":"/exam-media/ga-a1-m02/hoeren-familie.mp3","duration_seconds":23,"audio_script_staff_only":"Ansage: Hören Sie den Dialog. Frau: Hallo! Das ist meine Familie. Das ist mein Bruder Omar. Er ist 16 Jahre alt und Schüler. Mann: Und wer ist das? Frau: Das ist meine Mutter Laila. Sie ist Ärztin und sehr freundlich."}},{"id":"GA-A1-M02-H02","order":10,"skill":"hoeren","activity_type":"listening","learning_objective":"Comprendre la profession de la mère","theme":"Hören Familie","focus":"Beruf der Mutter","difficulty":"semi_guided","instruction":"Hören Sie noch einmal. Wählen Sie die richtige Antwort.","prompt":"Was ist die Mutter von Beruf?","points":1,"choices":[{"id":"A","text":"Lehrerin"},{"id":"B","text":"Ärztin"},{"id":"C","text":"Studentin"}],"correct_answer":"B","explanation":"Sie sagt: Sie ist Ärztin.","positive_feedback":"Sehr gut — Ärztin.","common_error":"Schüler bezieht sich auf Omar, nicht auf die Mutter.","media":{"audio_url":"/exam-media/ga-a1-m02/hoeren-familie.mp3","duration_seconds":23,"audio_script_staff_only":"Ansage: Hören Sie den Dialog. Frau: Hallo! Das ist meine Familie. Das ist mein Bruder Omar. Er ist 16 Jahre alt und Schüler. Mann: Und wer ist das? Frau: Das ist meine Mutter Laila. Sie ist Ärztin und sehr freundlich."}},{"id":"GA-A1-M02-S01","order":11,"skill":"schreiben","activity_type":"writing","learning_objective":"Écrire une courte présentation de sa famille","theme":"Schreiben Familie","focus":"haben + Familie + Beruf","difficulty":"semi_guided","instruction":"Schreiben Sie 4–6 kurze Sätze. Nutzen Sie: Ich habe … / Das ist mein/meine … / Er/Sie ist … Jahre alt / Er/Sie ist … (Beruf oder Adjektiv).","prompt":"Stellen Sie 2–3 Personen Ihrer Familie vor (Name, Relation, Alter oder Beruf, ein Adjektiv).","points":4,"recommended_words":40,"sample_answer_staff_only":"Ich heiße Amine. Ich habe eine Schwester und einen Bruder. Meine Schwester heißt Nadia. Sie ist 20 Jahre alt und Studentin. Mein Bruder ist nett. Meine Mutter ist Lehrerin.","rubric":[{"id":"task_completion","label":"Famille présentée (personnes / relation)","max_points":2},{"id":"vocabulary","label":"Vocabulaire famille / métier A1","max_points":1},{"id":"grammar_and_spelling","label":"haben / mein-meine compréhensibles","max_points":1}],"auto_grade_as_certain":false},{"id":"GA-A1-M02-O01","order":12,"skill":"sprechen","activity_type":"speaking","learning_objective":"Présenter oralement deux personnes de sa famille","theme":"Sprechen Familie","focus":"wer / wie alt / Beruf","difficulty":"semi_guided","instruction":"Sprechen Sie laut. Sie können aufnehmen oder üben ohne Mikrofon. Nutzen Sie die Karte Satz für Satz.","prompt":"Stellen Sie zwei Personen aus Ihrer Familie vor.","points":4,"speaking_card":"1) Guten Tag!\n2) Das ist meine/mein … (Mutter/Vater/Schwester/Bruder).\n3) Er/Sie heißt …\n4) Er/Sie ist … Jahre alt. / Er/Sie ist … (Beruf).\n5) Er/Sie ist nett / freundlich.","sample_answer_staff_only":"Guten Tag. Das ist meine Mutter. Sie heißt Fatima. Sie ist 45 Jahre alt und Ärztin. Sie ist sehr freundlich. Das ist mein Bruder. Er heißt Samir. Er ist Schüler.","rubric":[{"id":"task_completion","label":"Deux personnes + relation","max_points":2},{"id":"intelligibility","label":"Intelligibilité","max_points":1},{"id":"structures","label":"Structures A1 (haben, mein/meine)","max_points":1}],"mic_fallback":"Sans micro : lisez la carte à voix haute, puis importez un fichier audio si autorisé.","auto_grade_as_certain":false},{"id":"GA-A1-M02-R01","order":13,"skill":"revision","activity_type":"single_choice","learning_objective":"Réviser la question pour identifier une personne","theme":"Revision","focus":"wer","difficulty":"guided","instruction":"Kurze Revision. Wählen Sie die richtige Frage.","prompt":"Sie möchten wissen, welche Person das ist. Was fragen Sie?","points":1,"choices":[{"id":"A","text":"Wie alt sind Sie?"},{"id":"B","text":"Wer ist das?"},{"id":"C","text":"Was kostet das?"}],"correct_answer":"B","explanation":"Wer ist das? fragt nach der Person.","positive_feedback":"Revision gelungen.","common_error":"Was kostet das? gehört zum Einkaufen, nicht zur Familie."}]}$json$::jsonb,
